"""Stage pinned host plus six independent shoreline prototypes in an offline project."""
from pathlib import Path
import json,shutil,subprocess,tarfile
SRC=Path(__file__).resolve().parent;ROOT=SRC.parents[3];OUT=ROOT/'output/alcatraz-foam-424';QA=OUT/'project'
BASE='d7b57574d359952858319d17b43722651a0fcbcb'
def main():
 QA.mkdir(parents=True,exist_ok=True);(OUT.parent/'.gdignore').touch()
 # This directory is generated by this script. Remove stale prototype aliases
 # before staging a newer owner revision, preserving caches and other QA data.
 staged=QA/'assets/landmarks/alcatraz_island'
 if staged.exists():shutil.rmtree(staged)
 # Re-extract only owner assets / scene, never copy them into the art branch.
 proc=subprocess.Popen(['git','archive',BASE,'assets/landmarks/alcatraz_island','scenes/landmark/alcatraz_island.gd','scenes/landmark/alcatraz_island.tscn'],cwd=ROOT,stdout=subprocess.PIPE)
 with tarfile.open(fileobj=proc.stdout,mode='r|') as tar:tar.extractall(QA,filter='data')
 assert proc.wait()==0
 # Accepted technical #801 kit is preview context only. Never copy into the branch.
 nature='af31975750619983f4c93c83486092612eef73b9'
 names=['alc_rock_a','alc_rock_b','alc_rock_c','alc_shrub','alc_shrub_b','alc_grass_tuft']
 rels=['assets/landmarks/alcatraz_island/'+n+suf for n in names for suf in ['.glb','.glb.import']]+['assets/landmarks/alcatraz_island/alc_nature_material.tres','assets/landmarks/alcatraz_island/alc_nature_placements.json']
 proc=subprocess.Popen(['git','archive',nature,*rels],cwd=ROOT,stdout=subprocess.PIPE)
 with tarfile.open(fileobj=proc.stdout,mode='r|') as tar:tar.extractall(QA,filter='data')
 assert proc.wait()==0

 # Approved dock props are context, archived only into ignored QA project.
 dock='cc59ef9fb47fb398eefccded423aeab85d16839f'
 names=['alc_dock_bollard','alc_dock_crates','alc_dock_shelter','alc_dock_welcome','alc_dock_planter']
 rels=['assets/landmarks/alcatraz_island/'+n+suf for n in names for suf in ['.glb','.glb.import']]+['assets/landmarks/alcatraz_island/alc_dock_material.tres','assets/landmarks/alcatraz_island/alc_dock_placements.json']
 proc=subprocess.Popen(['git','archive',dock,*rels],cwd=ROOT,stdout=subprocess.PIPE)
 with tarfile.open(fileobj=proc.stdout,mode='r|') as tar:tar.extractall(QA,filter='data')
 assert proc.wait()==0

 def copy(rel):
  src=ROOT/rel;dst=QA/rel
  if src.is_dir():shutil.copytree(src,dst,dirs_exist_ok=True)
  else:dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dst)
 for p in json.loads((ROOT/'tools/dev/scene_bench/fixtures/avatar-dependencies.json').read_text()):copy(p.removeprefix('res://'))
 for p in ['modules/avatar','modules/farm/farm_camera.gd','modules/farm/scene_pan.gd','assets/avatar/demo_denylist.json','assets/ui/icons/game/door-open.svg']:copy(p)
 for pat in ['alc_foam*','alc_shore*','alc_buoy*','alc_driftwood*']:
  for p in (ROOT/'assets/landmarks/alcatraz_island').glob(pat):copy(str(p.relative_to(ROOT)))
 manifest=json.loads((ROOT/'assets/avatar/parts_manifest.json').read_text());manifest['parts']=[p for p in manifest['parts'] if p['id'] in ['body00','eyes00','hairhat0','cloth0','shoes0']]
 (QA/'assets/avatar/parts_manifest.json').write_text(json.dumps(manifest))
 for name in ['review.gd','verify.gd','android_review.gd','prepare_android.gd','configure_imports.gd']:
  if (SRC/name).exists():shutil.copy2(SRC/name,QA/name)
 (QA/'review.tscn').write_text('[gd_scene load_steps=2 format=3]\n[ext_resource type="Script" path="res://review.gd" id="1"]\n[node name="AlcatrazFoamReview" type="Node"]\nscript=ExtResource("1")\n')
 (QA/'project.godot').write_text('''config_version=5
[application]
config/name="Alcatraz Foam 424 QA"
config/features=PackedStringArray("4.7", "Mobile")
config/use_custom_user_dir=true
config/custom_user_dir_name="SensenAlcatrazFoam424QA"
run/main_scene="res://review.tscn"
[autoload]
Avatar="*res://modules/avatar/avatar_service.gd"
[display]
window/size/viewport_width=720
window/size/viewport_height=800
window/size/window_width_override=720
window/size/window_height_override=800
window/stretch/mode="disabled"
[input_devices]
pointing/emulate_mouse_from_touch=true
[rendering]
renderer/rendering_method="mobile"
renderer/rendering_method.mobile="mobile"
anti_aliasing/quality/msaa_3d=2
lights_and_shadows/directional_shadow/size=2048
lights_and_shadows/directional_shadow/soft_shadow_filter_quality=2
textures/vram_compression/import_s3tc_bptc=true
textures/vram_compression/import_etc2_astc=true
''')
 print(QA)
if __name__=='__main__':main()
